		return
	end

	if 玩家数据[数字id].摊位数据 ~= nil and 序号 ~= 3699 and 序号 ~= 3700 and 序号 ~= 3720 and 序号 ~= 3721 and 序号 ~= 3722 and 序号 ~= 3723 and 序号 ~= 3724 then
		常规提示(数字id, "#Y/摆摊状态下禁止此种行为")

		return
