	if 序号 == 3699 then
		local id = 数字id

		发送数据(玩家数据[id].连接id, 3503, 玩家数据[id].角色:取装备数据())
		发送数据(玩家数据[id].连接id, 3506, 玩家数据[id].角色:取灵饰数据())
