					广播消息({
						频道 = "sj",
						内容 = format("#R【抽奖系统】#Y玩家：#R/" .. 玩家数据[数字id].角色.数据.名称 .. "#Y抽奖获得#G" .. 随机数 .. "级" .. 名称 .. "#Y奖池物品剩余#R" .. 剩余物品个数 .. "个#1")
