	elseif 等级 == 2 then
		名称 = "飞蝗石"
	elseif 等级 == 3 then
		名称 = "铁蒺藜"
	elseif 等级 == 4 then
		名称 = "无影神针"
	elseif 等级 == 5 then
		名称 = "孔雀翎"
	elseif 等级 == 6 then
		名称 = "含沙射影"
	elseif 等级 == 7 then
		名称 = "回龙摄魂标"
	elseif 等级 == 8 then
		名称 = "寸阴若梦"
	elseif 等级 == 9 then
