function 道具处理类:使用法宝(连接id, id, 编号)
	local 道具id = 玩家数据[id].角色.数据.法宝[编号]

	if 道具id == nil or self.数据[道具id] == nil then
		常规提示(id, "#Y你没有这件法宝")
		self:索要法宝(连接id, id)

		return
	end

	local 名称 = self.数据[道具id].名称

	if 名称 == "五色旗盒" then
		if self.数据[道具id].魔法 <= 0 then
			常规提示(id, "#Y你的法宝灵气不足")

			return
		elseif 玩家数据[id].角色.数据.等级 < 30 then
			常规提示(id, "#Y你的等级不足以使用此法宝")

			return
		end

		local aa = "请选择你要进行的操作："
		local xx = {
			"合成导标旗",
			"补充合成旗"
		}

		发送数据(连接id, 1501, {
			名称 = "五色旗盒",
			对话 = aa,
			选项 = xx
		})

		玩家数据[id].最后操作 = "合成旗1"
		玩家数据[id].法宝id = 编号

		return
	elseif 名称 == "月光宝盒" then
		if self.数据[道具id].魔法 <= 0 then
			常规提示(id, "#Y你的法宝灵气不足")

			return
		end

		if 玩家数据[id].角色.数据.等级 < 30 then
			常规提示(id, "#Y你的等级不足以使用此法宝")

			return
		end

		local aa = "请选择你要进行的操作："
		local xx = {
			"送我过去",
			"在这里定标"
		}

		发送数据(连接id, 1501, {
			名称 = "月光宝盒",
			对话 = aa,
			选项 = xx
		})

		玩家数据[id].最后操作 = "月光宝盒"
		玩家数据[id].法宝id = 编号

		return
	end

	常规提示(id, "#Y此类型法宝当前不可用")
end

