		常规提示(id, "#Y你的门派不允许你使用这样的法宝")

		return
	elseif 名称 == "五火神焰印" and 门派 ~= "魔王寨" then
		常规提示(id, "#Y你的门派不允许你使用这样的法宝")

		return
