function 道具处理类:开启福利宝箱(id, 任务id)
	if 任务数据[任务id] == nil then
		常规提示(id, "#Y这个宝箱已经被其他玩家开启过了")

		return
	end

	if 掉率模式 == 1 then
		取福利宝箱奖励(id)
	else
		if 添加活动次数(id, "福利宝箱") == false then
			return
		end

		取福利宝箱奖励(id)
	end

	地图处理类:删除单位(任务数据[任务id].地图编号, 任务数据[任务id].单位编号)

	任务数据[任务id] = nil
end

function 道具处理类:开启修炼宝箱(id, 任务id)
	if 任务数据[任务id] == nil then
		常规提示(id, "#Y这个修炼宝箱已经被其他玩家开启过了")

		return false
	end

	地图处理类:删除单位(任务数据[任务id].地图编号, 任务数据[任务id].单位编号)

	任务数据[任务id] = nil

	return true
end

