		内容 = format("#S(在线奖励)#R/%s#Y本日在线因此获得了游戏管理员赠送的#G/%s#Y", 玩家数据[id].角色.数据.名称, "获得10000点仙玉#2")
	})
	广播消息({
		频道 = "xt",
		内容 = format("#S(在线奖励)#R/%s#Y本日在线因此获得了游戏管理员赠送的#G/%s#Y", 玩家数据[id].角色.数据.名称, "获得80W银子#3")
	})
