function 道具处理类:炼药处理(连接id, 数字id, 数据)
	local 临时等级 = 玩家数据[数字id].角色:取生活技能等级("中药医理")
	local 临时消耗 = math.floor(临时等级 / 10) + 10

	if 玩家数据[数字id].角色.数据.活力 < 临时消耗 then
		常规提示(数字id, "本次操作需要消耗" .. 临时消耗 .. "点活力")

		return
	elseif 临时等级 < 1 then
		常规提示(数字id, "您的中药医理技能尚未达到1级，无法进行炼药操作")

		return
	elseif 玩家数据[数字id].角色.数据.银子 < 5000 then
		常规提示(数字id, "炼药需要消耗5000两银子")

		return
	end

	玩家数据[数字id].角色:扣除银子(5000, 0, 0, "炼药消耗", 1)

	玩家数据[数字id].角色.数据.活力 = 玩家数据[数字id].角色.数据.活力 - 临时消耗

	体活刷新(数字id)

	local 物品表 = {}
	物品表 = {
		"金香玉",
		"小还丹",
		"千年保心丹",
		"风水混元丹",
		"定神香",
		"蛇蝎美人",
		"九转回魂丹",
		"佛光舍利子",
		"十香返生丸",
		"金创药",
		"金创药",
		"金创药",
		"金创药",
		"五龙丹"
	}
	local 临时物品 = 物品表[取随机数(1, #物品表)]
	local 临时品质 = 0
	临时品质 = 取随机数(math.floor(临时等级), 临时等级 * 2)

	常规提示(数字id, "#W/恭喜你成功炼制出了#R/" .. 临时物品)
	self:给予道具(数字id, 临时物品, 1, 临时品质)
	道具刷新(数字id, 1)
end

function 道具处理类:染色处理(连接id, id, 数据)
	local 彩果数量 = 10

	for n = 1, #数据 do
		彩果数量 = 彩果数量 + 数据[n]
	end

	if 扣除道具(id, "彩果", 彩果数量) ~= true then
		return
	else
		常规提示(id, "染色成功！")

		玩家数据[id].角色.数据.染色组 = 数据

		发送数据(连接id, 30, 数据)
		地图处理类:更改染色(id, 数据, 玩家数据[id].角色.数据.染色方案)
	end
end

连抽列表 = {}

function 道具处理类:迷宫宝箱处理(连接id, id, 连抽次数)
	if 神秘宝箱[id] == nil then
		常规提示(id, "数据异常！")

		return
	end

	local 序号 = 神秘宝箱[id].中奖
	local 名称 = 神秘宝箱[id][序号].名称
	local 快捷 = {
		随机四级法宝 = 4,
		金刚石 = 1,
		夜光珠 = 1,
		属性转换符 = 1,
		九转金丹 = 1,
		超级通灵重置丹 = 1,
		源生之灵 = 1,
		高级魔兽要诀 = 1,
		五行石 = 1,
		龙鳞 = 1,
		通灵神符 = 0,
		中 = 1,
	秋 = 1,
	节 = 1,
	快 = 1,
	乐 = 1,
		祥瑞坐骑礼包 = 1,
		种族坐骑礼包 = 1,
		七彩石 = 1,
		特殊魔兽要诀 = 1,
		百炼晶石碎片 = 1,
		特技石 = 1,
		定魂珠 = 1,
		通灵重置丹 = 1,
		随机三级法宝 = 3,
		还魂秘术 = 1,
		黄帝内经 = 1,
		六艺修行书 = 1,
		驾驭宝典 = 1,
		避水珠 = 1,
		高级通灵重置丹 = 1,
		特效石碎片 = 1,
		召唤兽内丹 = 1,
		通灵神戒 = 0,
		蚩尤武诀 = 1,
		召唤兽蛋 = 1,
		魔兽要诀 = 1,
		神兜兜 = 1,
		坐骑内丹 = 1,
		高级召唤兽内丹 = 1,
		易经丹 = 1,
		修炼果 = 1,
		通灵神臂 = 0,
		超级金柳露 = 取随机数(3, 5),
		金柳露 = 取随机数(5, 10),
		钟灵石 = 取随机数(1, 2),
		彩果 = 取随机数(2, 3),
		百炼精铁 = 取随机数(10, 12),
		制造指南书 = 取随机数(10, 12),
		元灵晶石 = 取随机数(8, 12),
		灵饰指南书 = 取随机数(8, 12),
		随机法宝 = math.ceil(取随机数(1, 200) / 100),
		魔兽残卷 = 取随机数(1, 3)
	}

	for i = 1, #宝石列表 do
		快捷[宝石列表[i]] = 取随机数(2, 5)
	end

	if 快捷[名称] ~= nil then
		local mc1 = 名称
		local jp = nil

		if 名称 == "宝石" then
			mc1 = 宝石列表[取随机数(1, #宝石列表)]
		elseif 名称 == "源生之灵" or 名称 == "召唤兽蛋" then
			jp = 神秘宝箱[id][序号].说明
		elseif string.find(名称, "法宝") then
			mc1 = "法宝"
		end

		奖励名称[id] = 快捷给道具(id, mc1, 快捷[名称], jp)

		if 连抽次数 ~= nil then
			if 连抽列表[id] == nil then
				连抽列表[id] = {}
			end

			连抽列表[id][#连抽列表[id] + 1] = 奖励名称[id]

			if 连抽次数 == #连抽列表[id] then
				local mc = nil

				for i = 1, #连抽列表[id] do
					if i == 1 then
						mc = 连抽列表[id][i]
					else
						mc = mc .. "、" .. 连抽列表[id][i]
					end
				end

				广播消息({
					频道 = "xt",
					内容 = format("#S(幻域迷宫)#R/%s#Y开启#S" .. 连抽次数 .. "#Y次迷宫宝箱获得了#G/%s#Y" .. "#" .. 取随机数(1, 110), 玩家数据[id].角色.数据.名称, mc)
				})

				连抽列表[id] = {}

				return
			end
		elseif 神秘宝箱[id][序号].广播 ~= false then
			广播消息({
				频道 = "xt",
				内容 = format("#S(幻域迷宫)#R/%s#Y开启迷宫宝箱获得了#G/%s#Y" .. "#" .. 取随机数(1, 110), 玩家数据[id].角色.数据.名称, 奖励名称[id])
			})
		end
	end

	神秘宝箱[id] = nil
end

function 道具处理类:神秘宝箱处理(连接id, id, 数据, 连抽次数)
	if 神秘宝箱[id] == nil then
		常规提示(id, "数据异常！")

		return
	end

	local 序号 = 神秘宝箱[id].中奖
	local 名称 = 神秘宝箱[id][序号].名称
	local 随机数 = ygsj()
	local 快捷 = {
		["神行百变·坐骑礼包"] = 1,
		通灵神戒 = 0,
		通灵神符 = 0,
		超级金柳露 = 10,
		属性转换符 = 5,
