		["12技能胚子召唤兽礼包"] = 1,
		["14技能胚子召唤兽礼包"] = 1,
		["16技能胚子召唤兽礼包"] = 1,
		["18技能胚子召唤兽礼包"] = 1,
		["20技能胚子召唤兽礼包"] = 1,
		百炼晶石碎片 = 取随机数(2, 3),
		神兜兜 = 取随机数(1, 5),
		九转金丹 = 取随机数(1, 5),
		修炼果 = 取随机数(1, 5),
		资质丸 = 取随机数(1, 2),
		月饼 = 取随机数(1, 3),
		金砖 = 取随机数(1, 3)


	}

	if 宝石列表1[名称] ~= nil then
		奖励名称[id] = 快捷给道具(id, 名称, 取随机数(4, 8))

		广播消息({
			频道 = "xt",
			内容 = format("#S(幸运抽奖)#R/%s#Y在抽奖使者处获得了#G/%s#Y" .. "#" .. 取随机数(1, 110), 玩家数据[id].角色.数据.名称, 奖励名称[id])
		})
	elseif 名称 == "星辉石" then
		奖励名称[id] = 快捷给道具(id, 名称, 取随机数(3, 6))

		广播消息({
			频道 = "xt",
			内容 = format("#S(幸运抽奖)#R/%s#Y在抽奖使者处获得了#G/%s#Y" .. "#" .. 取随机数(1, 110), 玩家数据[id].角色.数据.名称, 奖励名称[id])
		})
	elseif 快捷[名称] ~= nil then
		奖励名称[id] = 快捷给道具(id, 名称, 快捷[名称])

		if 连抽次数 ~= nil then
			if 连抽列表[id] == nil then
				连抽列表[id] = {}
			end

			连抽列表[id][#连抽列表[id] + 1] = 奖励名称[id]

			if 连抽次数 == #连抽列表[id] then
				local mc = nil

				for i = 1, #连抽列表[id] do
					if i == 1 then
						mc = 连抽列表[id][i]
					else
						mc = mc .. "、" .. 连抽列表[id][i]
					end
				end

				广播消息({
