取指南书种类 = function()
	local aa = ygsj(7)

	if aa == 1 then
		return 18 + ygsj(2)
	elseif aa == 2 then
		return 21
	elseif aa == 3 or aa > 6 then
		return ygsj(18)
	elseif aa == 4 then
		return 21 + ygsj(2)
	else
		return 19 + aa
	end
end

function 道具处理类:给予书铁(id, 等级, 类型, 数量)
	数量 = 数量 or 1

	if 类型 == nil then
		self.临时随机 = ygsj()

		if self.临时随机 <= 50 then
			self.书铁名称 = "制造指南书"
		else
			self.书铁名称 = "百炼精铁"
		end

		local 书铁等级 = 取随机数(等级[1] * 10, 等级[2] * 10)
		local 书铁种类 = 取指南书种类()
		书铁等级 = math.floor(书铁等级 / 10) * 10

		self:给予道具(id, self.书铁名称, 书铁等级, 书铁种类, 数量)

		return {
			self.书铁名称,
			书铁等级,
			书铁种类
		}
	elseif 类型 == "指南书" then
		self.书铁名称 = "制造指南书"
		local 书铁等级 = 取随机数(等级[1] * 10, 等级[2] * 10)
		local 书铁种类 = 取指南书种类()
		书铁等级 = math.floor(书铁等级 / 10) * 10

		self:给予道具(id, self.书铁名称, 书铁等级, 书铁种类, 数量)

		return {
			self.书铁名称,
			书铁等级,
			书铁种类
		}
	elseif 类型 == "精铁" then
		self.书铁名称 = "百炼精铁"
		local 书铁等级 = 取随机数(等级[1] * 10, 等级[2] * 10)
		local 书铁种类 = 取指南书种类()
		书铁等级 = math.floor(书铁等级 / 10) * 10

		self:给予道具(id, self.书铁名称, 书铁等级, 书铁种类, 数量)

		return {
			self.书铁名称,
			书铁等级,
			书铁种类
		}
	end
end

