				方向 = 1,
				x = 62,
				y = 64,
				名称 = 名称
			}

			发送数据(玩家数据[id].连接id, 1027, {
				tx
			})

			return
		else
			常规提示(id, "这不是你的房子或者不是庭院")

			return
		end
	elseif 名称 == "神兜兜" or 名称 == "神兜兜(专属)" then
