			if self.数据[玩家数据[id].角色.数据.法宝[n]] == nil then
				玩家数据[id].角色.数据.法宝[n] = nil
			else
				self.发送数据.道具[n] = table.loadstring(table.tostring(self.数据[玩家数据[id].角色.数据.法宝[n]]))

